def _union_version(union):
    """V2 (SF1): CP2 v3 version binding checked BEFORE any union status use. The union's
    self-reported module, design_freeze_sha256, scheme and producer_sha256 must equal the pinned
    v3 values exactly; returns None, else the refusal text. These fields stop cross-version use,
    not forgery: union origin remains prerequisite identity_union_census_cp2."""
    if type(union) is not dict:
        return 'CP2 union is not an object; version fields absent'
    for key, expected in CP2_UNION_VERSION:
        value = union.get(key)
        if type(value) is not str or value != expected:
            shown = value[:80] if type(value) is str else type(value).__name__
            return 'CP2 union %s %r is not the pinned v3 value %r' % (key, shown, expected)
    return None


